360	// CancelPlanChange 在安排生效前取消它，取消后账户继续沿用当前套餐。
361	// 没有待生效安排时取消也成功；已生效的切换不会被撤回。
362	// 欠费停用期间也可以取消，取消不清除欠费、不解除停用。
363	// 账户不存在、订阅已终止（含已到终止时刻）时失败。
364	func (s *Service) CancelPlanChange(accountID string) error {
365		if accountID == "" {
366			return invalidf("account id is empty")
367		}
368		s.mu.Lock()
369		defer s.mu.Unlock()
370		acc, ok := s.accounts[accountID]
371		if !ok {
372			return ErrAccountNotFound
373		}
374		// 已到生效月份月初零点的安排视为已生效，不可撤回；已终止订阅段无当前订阅。
375		s.settleLocked(acc, s.nowUTC())
376		if acc.sub == nil {
377			return ErrSubscriptionNotFound
378		}
379		acc.sub.pending = nil
380		return nil
381	}
