456	// RecordEvent 上报一条用量事件。
457	//
458	// 事件按发生时刻归入 UTC 自然月账期；事件发生时刻必须属于某段实际订阅期间
459	// （开通时刻计入、终止时刻不计入），空档期间与晚于当前时刻的事件被拒绝。
460	// 订阅终止后仍可补报旧订阅期间且尚未出账的用量。
461	// 事件标识在同一账户内去重：完全相同的重报返回原结果且不重复累计——
462	// 即使发生在取消、重新开通之后也成功；相同标识但时刻或数量不同返回
463	// ErrEventConflict。
464	// 已出账月份拒绝新事件；账户因到期欠费停用时拒绝新增事件；
465	// 但此前已接收事件的完全相同重报始终成功。
466	func (s *Service) RecordEvent(e Event) (EventResult, error) {
467		if e.AccountID == "" {
468			return EventResult{}, invalidf("account id is empty")
469		}
470		if e.EventID == "" {
471			return EventResult{}, invalidf("event id is empty")
472		}
473		if e.Quantity < 0 {
474			return EventResult{}, invalidf("event %q has negative quantity %d", e.EventID, e.Quantity)
475		}
476		if e.At.IsZero() {
477			return EventResult{}, invalidf("event %q has zero timestamp", e.EventID)
478		}
479		at := e.At.UTC()
480	
481		s.mu.Lock()
482		defer s.mu.Unlock()
483	
484		acc, ok := s.accounts[e.AccountID]
485		if !ok {
486			return EventResult{}, ErrAccountNotFound
487		}
488	
489		now := s.nowUTC()
490		// 进入即补齐已到期的换套餐/取消，保证并发下各操作观察到一致的分段状态。
491		s.settleLocked(acc, now)
492	
493		// 从未开通订阅的账户没有任何订阅段。
494		if acc.sub == nil && len(acc.history) == 0 {
495			return EventResult{}, ErrSubscriptionNotFound
496		}
497	
498		// 去重优先：完全相同的重报即使发生在出账后、停用期间、取消或重新开通
499		// 之后也返回成功。
500		if prev, ok := acc.events[e.EventID]; ok {
501			if !prev.at.Equal(at) || prev.qty != e.Quantity {
502				return EventResult{}, ErrEventConflict
503			}
504			return EventResult{Accepted: false, Period: prev.period}, nil
505		}
506	
507		if at.After(now) {
508			return EventResult{}, ErrEventInFuture
509		}
510		// 事件发生时刻必须落在某段实际订阅期间：[activatedAt, end)。
511		if activeSegmentAtLocked(acc, at) == nil {
512			return EventResult{}, ErrEventBeforeSubscription
513		}
514	
515		period := MonthOf(at)
516		if _, billed := acc.bills[period]; billed {
517			return EventResult{}, ErrMonthBilled
518		}
519		if s.isSuspendedLocked(acc, now) {
520			return EventResult{}, ErrSuspended
521		}
522	
523		total, ok := addNonNeg(acc.usage[period], e.Quantity)
524		if !ok {
525			return EventResult{}, ErrOverflow
526		}
527		// 所有校验通过后才落库：失败不消耗事件标识。
528		acc.events[e.EventID] = eventRecord{at: at, qty: e.Quantity, period: period}
529		acc.usage[period] = total
530		return EventResult{Accepted: true, Period: period}, nil
531	}
