693	// Status 返回账户状态：各月累计用量、各账单余额以及当前是否因欠费停用。
694	func (s *Service) Status(accountID string) (AccountStatus, error) {
695		if accountID == "" {
696			return AccountStatus{}, invalidf("account id is empty")
697		}
698		s.mu.Lock()
699		defer s.mu.Unlock()
700		acc, ok := s.accounts[accountID]
701		if !ok {
702			return AccountStatus{}, ErrAccountNotFound
703		}
704	
705		now := s.nowUTC()
706		// 查询即让已到期安排/取消生效：月初零点或终止时刻之后无需上报用量或出账，
707		// 当前条件与订阅状态立即更新。
708		s.settleLocked(acc, now)
709	
710		// 订阅是否生效以实际开通时刻为界：提前登记、开通时刻尚未到达的订阅仍
711		// 保存在 acc.sub 中（再次开通、安排换套餐、登记取消均按已有订阅的规则
712		// 处理），但查询时刻不显示为有效订阅。到达开通时刻即生效，不按开通月份
713		// 提前生效；时刻按同一瞬间比较，使用带时区的时间结果一致。
714		active := acc.sub != nil && !now.Before(acc.sub.activatedAt)
715	
716		periodSet := make(map[Month]struct{}, len(acc.usage)+len(acc.bills))
717		for m := range acc.usage {
718			periodSet[m] = struct{}{}
719		}
720		for m := range acc.bills {
721			periodSet[m] = struct{}{}
722		}
723		periods := make([]Month, 0, len(periodSet))
724		for m := range periodSet {
725			periods = append(periods, m)
726		}
727		sortMonths(periods)
728	
729		st := AccountStatus{
730			AccountID:    accountID,
731			Subscribed:   active,
732			Suspended:    s.isSuspendedLocked(acc, now),
733			MonthlyUsage: make([]Usage, 0, len(periods)),
734			Bills:        make([]BillSummary, 0, len(acc.bills)),
735		}
736		// 仅实际生效的订阅才展示当前套餐条件、待换套餐安排与已安排终止时刻；
737		// 等待开通期间这些字段均为零值（查询不删除也不提前激活已登记订阅）。
738		if active {
739			st.CurrentTerms = acc.sub.terms
740			if acc.sub.pending != nil {
741				pending := *acc.sub.pending
742				st.PendingChange = &pending
743			}
744			if acc.sub.cancelEnd != nil {
745				end := *acc.sub.cancelEnd
746				st.ScheduledEnd = &end
747			}
748		}
749		for _, m := range periods {
750			st.MonthlyUsage = append(st.MonthlyUsage, Usage{Period: m, Total: acc.usage[m]})
751		}
752		for _, m := range periods {
753			if rec, ok := acc.bills[m]; ok {
754				b := rec.bill
755				st.Bills = append(st.Bills, BillSummary{
756					Period:   m,
757					TotalDue: b.TotalDue,
758					Paid:     b.Paid,
759					Balance:  b.Balance,
760					Settled:  b.Settled,
761					DueAt:    b.DueAt,
762				})
763			}
764		}
765		return st, nil
766	}
767	
768	// isSuspendedLocked 报告账户当前是否停用：
769	// 存在到达付款截止时刻仍有余额的账单。调用时持有 s.mu。
770	func (s *Service) isSuspendedLocked(acc *account, now time.Time) bool {
771		for _, rec := range acc.bills {
772			if !rec.bill.Settled && !now.Before(rec.bill.DueAt) {
773				return true
774			}
775		}
776		return false
777	}
778	
779	func sortMonths(ms []Month) {
780		sort.Slice(ms, func(i, j int) bool { return ms[i].Before(ms[j]) })
781	}
782	
783	// addNonNeg 返回两个非负 int64 之和；溢出时 ok=false。
784	func addNonNeg(a, b int64) (int64, bool) {
785		if a > maxInt64-b {
786			return 0, false
787		}
788		return a + b, true
789	}
790	
791	// mulNonNeg 返回两个非负 int64 之积；溢出时 ok=false。
792	func mulNonNeg(a, b int64) (int64, bool) {
793		if a == 0 || b == 0 {
794			return 0, true
795		}
796		if a > maxInt64/b {
797			return 0, false
798		}
799		return a * b, true
800	}
801	
802	// buildBill 依据套餐快照和账期总用量计算账单，所有金额运算做溢出检查。
803	func buildBill(accountID string, period Month, t PlanTerms, totalUsage int64) (Bill, error) {
804		overageUnits := int64(0)
805		if totalUsage > t.IncludedUnits {
806			overageUnits = totalUsage - t.IncludedUnits
807		}
808		overageFee, ok := mulNonNeg(overageUnits, t.OveragePrice)
809		if !ok {
810			return Bill{}, ErrOverflow
811		}
812		subtotal, ok := addNonNeg(t.MonthlyFee, overageFee)
813		if !ok {
814			return Bill{}, ErrOverflow
815		}
816		tax, ok := rateAmount(subtotal, t.TaxRateBasisPoints)
817		if !ok {
818			return Bill{}, ErrOverflow
819		}
820		totalDue, ok := addNonNeg(subtotal, tax)
821		if !ok {
822			return Bill{}, ErrOverflow
823		}
824		b := Bill{
825			AccountID:     accountID,
826			Period:        period,
827			Terms:         t,
828			TotalUsage:    totalUsage,
829			IncludedUnits: t.IncludedUnits,
830			OverageUnits:  overageUnits,
831			MonthlyFee:    t.MonthlyFee,
832			OverageFee:    overageFee,
833			Tax:           tax,
834			TotalDue:      totalDue,
835			Paid:          0,
836			Balance:       totalDue,
837			Settled:       totalDue == 0,
838			DueAt:         period.End().AddDate(0, 0, 7),
839		}
840		return b, nil
841	}
842	
843	// rateAmount 计算 amount*rate/10000 并四舍五入到分（非负数，半数向上）。
844	// 拆分商和余数计算以避免乘积溢出 int64。
845	func rateAmount(amount, rate int64) (int64, bool) {
846		const den = 10000
847		q, r := amount/den, amount%den
848		qr, ok := mulNonNeg(q, rate)
849		if !ok {
850			return 0, false
851		}
852		rr, ok := mulNonNeg(r, rate)
853		if !ok {
854			return 0, false
855		}
856		// 四舍五入：(rr + den/2) / den，rr < den*10001 < 1e8，加 den/2 不溢出。
857		add, ok := addNonNeg(qr, (rr+den/2)/den)
858		if !ok {
859			return 0, false
860		}
861		return add, true
862	}
863

