16		c := &fakeClock{t: start.UTC()}
17		return NewServiceWithClock(c.get), c
18	}
19	
20	func utc(y int, mo time.Month, d, h, mi int) time.Time {
21		return time.Date(y, mo, d, h, mi, 0, 0, time.UTC)
22	}
23	
24	func jan(y int) Month { return Month{Year: y, Month: time.January} }
25	func feb(y int) Month { return Month{Year: y, Month: time.February} }
26	func mar(y int) Month { return Month{Year: y, Month: time.March} }
27	
28	func mustPlan(t *testing.T, s *Service, p Plan) {
29		t.Helper()
30		if err := s.CreatePlan(p); err != nil {
31			t.Fatalf("create plan %q: %v", p.ID, err)
32		}
33	}
34	
35	func mustAccount(t *testing.T, s *Service, id string) {
36		t.Helper()
37		if err := s.CreateAccount(id); err != nil {
38			t.Fatalf("create account %q: %v", id, err)
39		}
40	}
41	
42	func TestCreateAccountAndPlanValidation(t *testing.T) {
43		s, _ := newTestService(utc(2026, 1, 15, 12, 0))
44		mustAccount(t, s, "acme")
45		if err := s.CreateAccount("acme"); !errors.Is(err, ErrAccountExists) {
46			t.Fatalf("dup account: %v", err)
47		}
48		if err := s.CreateAccount(""); !errors.Is(err, ErrInvalidArgument) {
49			t.Fatalf("empty account: %v", err)
50		}
51	
52		good := Plan{ID: "p", MonthlyFee: 100, IncludedUnits: 10, OveragePrice: 5, TaxRateBasisPoints: 1000}
53		mustPlan(t, s, good)
54		if err := s.CreatePlan(good); !errors.Is(err, ErrPlanExists) {
55			t.Fatalf("dup plan: %v", err)
56		}
57		for _, bad := range []Plan{
58			{ID: "", TaxRateBasisPoints: 0},
59			{ID: "n1", MonthlyFee: -1, TaxRateBasisPoints: 0},
60			{ID: "n2", IncludedUnits: -1, TaxRateBasisPoints: 0},
61			{ID: "n3", OveragePrice: -1, TaxRateBasisPoints: 0},
62			{ID: "n4", TaxRateBasisPoints: -1},
63			{ID: "n5", TaxRateBasisPoints: 10001},
64		} {
65			if err := s.CreatePlan(bad); !errors.Is(err, ErrInvalidArgument) {
66				t.Fatalf("plan %+v expected invalid, got %v", bad, err)
67			}
68		}
69		// 失败不改变已有记录。
70		if err := s.UpdatePlan(Plan{ID: "p", TaxRateBasisPoints: 20000}); !errors.Is(err, ErrInvalidArgument) {
71			t.Fatalf("bad update: %v", err)
72		}
73		if got := s.Status2("p"); got != good {
74			t.Fatalf("plan mutated after failed update: %+v", got)
75		}
76		if err := s.UpdatePlan(Plan{ID: "missing", TaxRateBasisPoints: 1}); !errors.Is(err, ErrPlanNotFound) {
77			t.Fatalf("update missing: %v", err)
78		}
79	}
80	
81	// TestService 内部用：直接读取套餐当前定义。
82	func (s *Service) Status2(id string) Plan {
83		s.mu.Lock()
84		defer s.mu.Unlock()
85		return s.plans[id]
86	}
